// Accept only application/json with {"text": "..."}. Browsers cannot send JSON to another
// origin without a CORS preflight, which the webhook's allowed origins refuse, so other
// web pages open in the browser cannot post notes here.
const MAX_LENGTH = 5000;
const { body, headers = {} } = $input.first().json;
const isJson = String(headers['content-type'] ?? '').startsWith('application/json');
const raw = isJson ? body?.text : undefined;
const text = typeof raw === 'string' ? raw.trim() : '';

if (!text) return [{ json: { valid: false, error: 'Send JSON like {"text": "your note"}' } }];
if (text.length > MAX_LENGTH) return [{ json: { valid: false, error: `Text is longer than ${MAX_LENGTH} characters` } }];
return [{ json: { valid: true, text } }];

// Check the model's JSON and build a safe note; fall back to the note's first words.
const MAX_TITLE_WORDS = 6;
const MAX_TITLE_LENGTH = 60;
const MAX_TAGS = 3;
const { text } = $('Validate input').first().json;

// The chain usually parses the model's JSON itself ({title, tags}); older output is {text: "<json>"}.
function readSuggestion(json) {
  if (json.title !== undefined || json.tags !== undefined) return json;
  try {
    return JSON.parse(json.text) ?? {};
  } catch {
    return {};
  }
}
const suggestion = readSuggestion($input.first().json);

// Letters (with their accents and combining marks), digits and spaces only, so the title is a safe file name.
const words = (value) => String(value ?? '').replace(/[^\p{L}\p{M}\p{N}\s]/gu, ' ').split(/\s+/).filter(Boolean);
const titleCase = (list) => list.map((word) => word[0].toUpperCase() + word.slice(1)).join(' ');
const shorten = (title) => (title.length <= MAX_TITLE_LENGTH ? title : title.slice(0, MAX_TITLE_LENGTH).replace(/\s+\S*$/, '') || title.slice(0, MAX_TITLE_LENGTH));

const fromModel = words(suggestion.title).slice(0, MAX_TITLE_WORDS);
const fromText = words(text).slice(0, MAX_TITLE_WORDS);
const usedFallback = fromModel.length === 0;
const title = shorten(titleCase(fromModel.length ? fromModel : fromText.length ? fromText : ['Quick', 'Capture']));

const modelTags = Array.isArray(suggestion.tags) ? suggestion.tags : String(suggestion.tags ?? '').split(/[\s,]+/);
const tags = [...new Set(modelTags.map((tag) => String(tag).toLowerCase().replace(/[^a-z0-9-]/g, '')))]
  .filter((tag) => /^[a-z0-9][a-z0-9-]*$/.test(tag) && tag !== 'capture')
  .slice(0, MAX_TAGS);

const content = [
  '---',
  `created: ${$now.toFormat('yyyy-MM-dd')}`,
  'type: idea',
  `tags: [${['capture', ...tags].join(', ')}]`,
  'status: active',
  '---',
  `# ${title}`,
  '',
  text,
  '',
  '## Links',
  '- [[Home]]',
  '',
].join('\n');

// Milliseconds in the name keep two quick captures with the same title from overwriting each other.
return [{ json: { fileName: `${$now.toFormat('yyyy-MM-dd HHmmssSSS')} ${title}.md`, title, content, usedFallback } }];
